using System; // Verify exact authoritative shelter and door transitions.
using System.Collections.Generic; // Independently count room and destination reservations.
using System.Diagnostics; // Report actual shelter-enabled scenario timing.
using System.Globalization; // Keep measurement output portable.
using System.IO; // Load independently executed previous-release references.
using Outbreak.Contracts; // Inspect persistent human destinations.
using Outbreak.Core; // Execute actual room and door behavior.
using Outbreak.Persistence; // Exercise the production JSON persistence boundary.
public static partial class Program // Keep shelter acceptance in the existing real-code suite.
{ // Begin shelter milestone checks.
    private static void CheckShelterCases() // Run behavior that can fail when shelter routing or doors are broken.
    { // Begin controlled scenarios.
        Check("Rooms require enclosed authored floors and bounded discovery", () => // Do not reinterpret an arbitrary outdoor floor patch as a safe building.
        { // Begin catalog checks.
            World world = EncounterScenarios.ShelterEntry(); Require(world.SheltersEnabled && world.ShelterRoomCount == 1 && !world.ShelterScanLimited, "Enclosed room was not discovered."); WorldMap map = WorldMap.Restore(world.Capture().map); map.Set(1, 4, Terrain.Grass); Require(new World(map, encounter: true).ShelterRoomCount == 0, "An outdoor leak was treated as an enclosed room."); // An ordinary terrain gap must invalidate enclosure.
            map = new WorldMap(100, 100); for (int y = 0; y < 83; y++) for (int x = 0; x < 100; x++) map.Set(x, y, Terrain.Floor); world = new World(map, encounter: true); Require(world.ShelterRoomCount == 0 && world.ShelterScanLimited, "Oversized floor scan silently cropped or claimed readiness."); Require(new World(new WorldMap(10000, 10000), encounter: true).ShelterRoomCount == 0, "Empty sparse world invented rooms."); // Bound floor work independently of the full world dimensions.
        }); // Finish catalog acceptance.
        Check("Human opens, enters, closes and retains its chosen shelter", () => // Observe the complete door lifecycle under a real pursuing zombie.
        { // Begin entry lifecycle.
            World world = EncounterScenarios.ShelterEntry(); Run(world, 1); int goal = world.ActorAt(0).shelterId; Require(goal > 0 && world.ActorAt(0).shelterState == ShelterState.Seeking && world.TerrainAt(5, 5) == Terrain.DoorClosed, "Human did not select a reachable shelter first."); Run(world, 5); Require(world.ActorAt(0).x == 6 && world.TerrainAt(5, 5) == Terrain.DoorOpen && world.TerrainRevision == 1, "Door opening did not consume an opportunity before entry."); World restored = Documents.ParseSave(State(world)); Run(world, 10); Run(restored, 10); Require(world.ActorAt(0).x == 4 && world.ActorAt(0).shelterState == ShelterState.Inside && world.TerrainAt(5, 5) == Terrain.DoorClosed && world.TerrainRevision == 2, "Human failed to enter and close behind itself."); Require(State(world) == State(restored), "Open-door save/resume changed entry or closing."); // A saved open doorway must continue identically.
            Run(world, 10); Run(restored, 10); Require(world.ActorAt(0).x == 2 && world.ActorAt(0).y == 3 && world.ActorAt(0).shelterId == goal && world.ActorAt(0).turnAtTick == 0, "Human abandoned a valid goal or crossed the closed door back into danger."); Require(State(world) == State(restored), "Persistent interior goal drifted after reload."); Inspect(world); // Reach an interior cell and keep the stable destination.
            TickClock clock = new TickClock(); string before = State(world); clock.Advance(1000, world.Step); Require(State(world) == before, "Paused shelter or doors advanced."); // Door actions obey the same pause boundary as infection.
        }); // Finish entry lifecycle.
        Check("Door closure never traps a body in its solid cell", () => // Keep an occupied doorway open until every occupant has actually left it.
        { // Begin occupancy fixture.
            WorldMap map = WorldMap.Restore(EncounterScenarios.ShelterEntry().Capture().map); map.Set(5, 5, Terrain.DoorOpen); World world = new World(map, 3, 1000, true); int id; world.TrySpawn(Species.Human, 4, 5, out id); world.TrySpawn(Species.Zombie, 5, 5, out id); SaveDocument saved = world.Capture(); saved.actors[0].shelterId = 51; saved.actors[0].shelterX = 2; saved.actors[0].shelterY = 3; saved.actors[0].shelterState = ShelterState.Inside; world = World.Restore(saved); Run(world, 1); Require(world.TerrainAt(5, 5) == Terrain.DoorOpen && world.ActorAt(1).x == 5, "Door closed through an occupying zombie."); Inspect(world); // Admission and physical solidity must remain consistent.
        }); // Finish doorway safety.
        Check("Full room admission and goal-cell reservations stay bounded", () => // Avoid routing an entire crowd onto one room or one destination cell.
        { // Begin comfort-capacity fixture.
            WorldMap map = WorldMap.Restore(EncounterScenarios.ShelterEntry().Capture().map); World world = new World(map, 3, 1000, true); int id; for (int i = 0; i < 8; i++) Require(world.TrySpawn(Species.Human, 7, 5 + i / 4, out id), "Crowd fixture spawn failed."); SaveDocument saved = world.Capture(); for (int i = 0; i < 8; i++) saved.actors[i].turnAtTick = 100; world = World.Restore(saved); Run(world, 30); int admitted = 0; Dictionary<int, int> goals = new Dictionary<int, int>(); for (int i = 0; i < world.Count; i++) { ActorState a = world.ActorAt(i); if (a.shelterId == 0) continue; admitted++; int key = a.shelterY * world.Width + a.shelterX, n; goals.TryGetValue(key, out n); goals[key] = n + 1; } Require(admitted == 7, "Comfort capacity did not admit exactly seven to fifteen floor cells."); foreach (int n in goals.Values) Require(n <= 4, "More than four humans reserved one interior cell."); Inspect(world); // Inbound reservations must count before the first person reaches the room.
        }); // Finish crowd admission.
        Check("Visible danger rejects a selected shelter and chooses another", () => // Do not retain a room goal just because it was safe at selection time.
        { // Begin unsafe-room reassessment.
            World world = EncounterScenarios.UnsafeShelter(); int old = world.ActorAt(0).shelterId; Run(world, 1); ActorState a = world.ActorAt(0); Require(a.rejectedShelterId == old && a.rejectedUntilTick == 51 && a.shelterId != old && a.shelterId > 0, "Visible internal danger did not replace the shelter goal."); World restored = Documents.ParseSave(State(world)); Run(world, 30); Run(restored, 30); Require(State(world) == State(restored), "Unsafe shelter reassessment diverged after resume."); Inspect(world); // Keep both destination and temporary rejection in the save contract.
        }); // Finish reassessment acceptance.
        Check("Unsafe room can be evacuated without another room", () => // Do not trap a human behind a door because no alternative shelter exists.
        { // Begin standalone evacuation fixture.
            WorldMap map = WorldMap.Restore(EncounterScenarios.ShelterEntry().Capture().map); World world = new World(map, 3, 1000, true); int id; world.TrySpawn(Species.Human, 4, 5, out id); world.TrySpawn(Species.Zombie, 2, 3, out id); SaveDocument saved = world.Capture(); saved.actors[0].bravery = -3; saved.actors[0].shelterId = 51; saved.actors[0].shelterX = 2; saved.actors[0].shelterY = 3; saved.actors[0].shelterState = ShelterState.Inside; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).shelterId == 0 && world.ActorAt(0).rejectedShelterId == 51 && world.TerrainAt(5, 5) == Terrain.DoorOpen, "Unsafe room did not open a reachable evacuation exit."); Run(world, 10); Require(world.ActorAt(0).x == 6 && world.TerrainAt(5, 5) == Terrain.DoorClosed, "Human did not exit and close the unsafe room behind itself."); Inspect(world); // The route is away from the observed internal zombie and uses an actual door action.
        }); // Finish evacuation acceptance.
        Check("A turning occupant makes a shelter visibly unsafe", () => // Reassess a real species transition instead of only seeding an existing zombie.
        { // Begin in-room infection fixture.
            WorldMap map = WorldMap.Restore(EncounterScenarios.ShelterEntry().Capture().map); World world = new World(map, 3, 1000, true); int id; world.TrySpawn(Species.Human, 2, 3, out id); world.TrySpawn(Species.Human, 4, 7, out id); SaveDocument saved = world.Capture(); for (int i = 0; i < 2; i++) { saved.actors[i].shelterId = 51; saved.actors[i].shelterX = 2; saved.actors[i].shelterY = i == 0 ? 3 : 7; saved.actors[i].shelterState = ShelterState.Inside; } saved.actors[0].bravery = -3; saved.actors[0].stress = 50; saved.actors[1].turnAtTick = 1; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(1).species == Species.Zombie && world.ActorAt(1).shelterId == 0, "Turning occupant retained its room admission."); Require(world.ActorAt(0).rejectedShelterId == 51 && world.ActorAt(0).shelterId != 51 && world.ActorAt(0).reaction == HumanReaction.Flight, "Human failed to reassess after witnessing an occupant turn."); Require(State(world) == State(Documents.ParseSave(State(world))), "Real shelter danger transition failed save validation."); // Infection and room danger share the same authoritative tick.
        }); // Finish dynamic danger acceptance.
        Check("Shelter corruption rejects and turning releases reservations", () => // Validate all new saved fields and species cleanup.
        { // Begin save validation fixture.
            World world = EncounterScenarios.ShelterEntry(); Run(world, 1); SaveDocument saved = world.Capture(); saved.actors[0].shelterId = 999999; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].shelterX = 7; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].shelterState = ShelterState.Inside; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].shelterState = (ShelterState)99; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].shelterId = 0; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.rulesVersion = EncounterRules.EscapeVersion; Reject(() => World.Restore(saved)); // Refuse missing rooms, wrong floor coordinates and incompatible modes.
            saved = world.Capture(); saved.actors[0].rejectedShelterId = 51; saved.actors[0].rejectedUntilTick = world.Tick + 51; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[0].turnAtTick = world.Tick + 1; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).species == Species.Zombie && world.ActorAt(0).shelterId == 0 && world.ActorAt(0).rejectedShelterId == 0 && world.ActorAt(0).shelterState == ShelterState.None, "Turning retained human shelter reservations."); Require(State(world) == State(Documents.ParseSave(State(world))), "Converted shelter state failed to round-trip."); // Conversion releases admission immediately without changing the stable identity.
        }); // Finish persisted-state acceptance.
        Check("Prototype-five saves preserve independent continuation", () => // Protect the previously verified infected escape milestone.
        { // Begin previous-release compatibility.
            string folder = Path.Combine(AppContext.BaseDirectory, "Fixtures"); World world = Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v5-input.json"))); Require(world.InfectedEscape && !world.SheltersEnabled, "Old escape run silently gained door behavior."); Run(world, 100); World expected = Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v5-expected.json"))); Require(State(world) == State(expected), "Prior escape continuation drifted."); // Expected state was generated from commit 0700d61.
        }); // Finish compatibility acceptance.
        Check("Mixed shelter encounter remains deterministic with doors enabled", () => // Exercise room admission and closing in a representative multi-body world.
        { // Begin the multi-body shelter run.
            World world = new World(EncounterScenarios.MixedShelterMap(), 214, 1000, true); int id; for (int i = 0; i < 24; i++) Require(world.TrySpawn(Species.Human, 4 + i % 6, 5 + i / 6, out id), "Mixed room spawn overlapped terrain."); world.TrySpawn(Species.Zombie, 12, 7, out id); Require(world.ShelterRoomCount == 2, "Default encounter has no actual room choices."); Stopwatch timer = Stopwatch.StartNew(); Run(world, 100); World restored = Documents.ParseSave(State(world)); Run(world, 100); Run(restored, 100); timer.Stop(); Require(State(world) == State(restored), "Mixed shelter continuation changed after save/load."); Inspect(world); results.Add("SHELTER BENCH 25 bodies, 2 rooms, 300 total executed ticks including resumed comparison: " + timer.Elapsed.TotalMilliseconds.ToString("0.00", CultureInfo.InvariantCulture) + " ms; admission, doors, reactions and infection enabled; rendering excluded."); // Keep actual shelter timing distinct from empty-floor movement benchmarks.
        }); // Finish multi-body readiness.
    } // Finish shelter acceptance cases.
} // Finish milestone checks.
